from pathlib import Path

SCRIPTS, FIX = Path(sys.argv[1]), Path(sys.argv[2])
FAILS = []


def check(name, cond, detail=""):
    print(("ok    " if cond else "FAIL  ") + name + ("" if cond else f"\n      {detail}"))
    if not cond:
        FAILS.append(name)


def load(fname, modname):
    spec = importlib.util.spec_from_file_location(modname, SCRIPTS / fname)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def run(mod, *argv):
    out, err = io.StringIO(), io.StringIO()
    saved = sys.argv
    sys.argv = ["prog", *map(str, argv)]
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = mod.main()
    finally:
        sys.argv = saved
    return code, out.getvalue(), err.getvalue()


GIT_ENV = dict(os.environ, GIT_AUTHOR_NAME="Fixture", GIT_AUTHOR_EMAIL="fixture@example.invalid",
               GIT_COMMITTER_NAME="Fixture", GIT_COMMITTER_EMAIL="fixture@example.invalid",
               GIT_CONFIG_NOSYSTEM="1")


def g(repo, *args, env=None):
    r = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, env=env or GIT_ENV)
    if r.returncode != 0:
        raise SystemExit(f"fixture setup failed: git {' '.join(args)}: {r.stderr}")
    return r.stdout.strip()


def commit(repo, msg, days_ago=0, author=None):
    ts = int(time.time()) - days_ago * 86400
    env = dict(GIT_ENV, GIT_AUTHOR_DATE=f"@{ts} +0000", GIT_COMMITTER_DATE=f"@{ts} +0000")
    args = ["commit", "-q", "--allow-empty", "-m", msg] + ([f"--author={author}"] if author else [])
    g(repo, *args, env=env)
    return g(repo, "rev-parse", "HEAD")


def put(path, text=""):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    return path


def npm_lock(pkgs):
    packages = {"": {"name": "app"}}
    packages.update({f"node_modules/{n}": {"version": v} for n, v in pkgs.items()})
    return json.dumps({"name": "app", "lockfileVersion": 3, "requires": True, "packages": packages}, indent=1) + "\n"


