def fake_post(url, payload, timeout=60):
    calls.append(payload)
    results = []
    for q in payload["queries"]:
        key = (q["package"]["ecosystem"], q["package"]["name"], q["version"])
        if q.get("page_token") == "p2":
            results.append({"vulns": [{"id": "GHSA-0000-0000-0003"}], "next_page_token": "p3"})
        elif q.get("page_token") == "p3":
            results.append({"vulns": [{"id": "MAL-2099-0001"}]})
        elif key == npm("left-pad", "1.0.1"):
            results.append({"vulns": [{"id": "GHSA-0000-0000-0001"}], "next_page_token": "p2"})
        elif key == pypi("foo-bar", "1.2.3"):
            results.append({"vulns": [{"id": "GHSA-0000-0000-0002"}]})
        else:
            results.append({})
    return {"results": results}


