# ---------------------------------------------------------------- end-of-life pins
eol = load("eol-check.py", "eol_check")
e = WORK / "eol"
put(e / ".nvmrc", "v18.20.4\n")
put(e / ".python-version", "3.12.3\n")
put(e / "Dockerfile", "FROM --platform=linux/amd64 node:20-alpine AS build\nRUN true\nFROM python:3.13-slim\n")
put(e / "docker-compose.yml", "services:\n  db:\n    image: postgres:13\n  app:\n    image: ghcr.io/acme/app:1.0\n"
                              "  cache:\n    image: \"redis\"\n")
put(e / "supabase/config.toml", "[db]\nport = 54322\nmajor_version = 15\n")
