put(en / ".nvmrc", "16\n")

ROWS = {("nodejs", "18.20.4", "pin", ".nvmrc", "eol"), ("nodejs", "20", "pin", "Dockerfile", "eol"),
        ("python", "3.13", "pin", "Dockerfile", "ok"), ("postgresql", "13", "pin", "docker-compose.yml", "eol"),
        ("python", "3.12.3", "pin", ".python-version", "behind"),
        ("postgresql", "15", "pin", "supabase/config.toml", "ok"), ("nodejs", "22.0.0", "floor", "package.json", "ok"),
        ("nextjs", "14.2.3", "range", "package.json", "eol"), ("python", "3.11", "floor", "pyproject.toml", "ok"),
        ("nodejs", "16", "ci", ".github/workflows/ci.yml", "eol")}
DATA = FIX / "eol-data"
ej = WORK / "eol.json"


def eol_rows(*extra):
    code, out, err = run(eol, "--repo", e, "--data", DATA, "--json", ej, *extra)
    rows = json.loads(ej.read_text())["rows"] if ej.exists() else []
    return code, out, {(r["product"], r["version"], r["kind"], r["file"], r["status"]): r["detail"] for r in rows}


code, out, rows = eol_rows("--today", "2026-11-02")
check("eol: pins from every file type resolve to the expected status on 2026-11-02",
      code == 2 and set(rows) == ROWS and "result: 5 of 10 pins" in out,
      f"code {code}, missing {sorted(ROWS - set(rows))}, extra {sorted(set(rows) - ROWS)}\n{out}")
check("eol: nested checkout skipped by default and said so", "skipped 1 nested checkouts" in out, out)

code, out, rows = eol_rows("--today", "2026-03-15")
soon = rows.get(("nodejs", "20", "pin", "Dockerfile", "eol-soon"), "")
check("eol: a cycle ending inside --warn-days is EOL-SOON", code == 2 and "46 days" in soon, f"{rows}\n{out}")

code, out, rows = eol_rows("--today", "2026-11-02", "--include-nested")
check("eol: --include-nested reads the nested checkout",
      ("nodejs", "16", "pin", "nested/.nvmrc", "eol") in rows, sorted(rows))

code, out, err = run(eol, "--repo", e, "--list")
check("eol: --list prints the pins with no lookup", code == 0 and "result: 10 version pins found" in out, out)

opened = []
real_read_text = pathlib.Path.read_text


def spy(self, *a, **k):
    opened.append(self.name)
    return real_read_text(self, *a, **k)


pathlib.Path.read_text = spy
try:
    list(eol.pins(str(e)))
finally:
    pathlib.Path.read_text = real_read_text
check("eol: .env is never opened; only pin files are read",
      ".env" not in opened and set(opened) == {".nvmrc", ".python-version", "Dockerfile", "docker-compose.yml",
                                                "config.toml", "package.json", "pyproject.toml", "ci.yml"},
      sorted(opened))
check("eol: wanted() refuses env and secret files",
      not any(eol.wanted(".", f) for f in (".env", ".env.local", "secrets.yml", "credentials.json"))
      and all(eol.wanted(d, f) for d, f in ((".", "Dockerfile.prod"), (".", "compose.yaml"),
                                            ("x/.github/workflows", "ci.yml"))))

